using System.ComponentModel.DataAnnotations;
using System.Text.Json.Serialization;
namespace BanhangcodeX.Models;
public class Customer { public int Id{get;set;} [MaxLength(30)] public string Code{get;set;}=""; [Required,MaxLength(160)] public string Name{get;set;}=""; [MaxLength(30)] public string? Phone{get;set;} [MaxLength(120)] public string? ZaloName{get;set;} [MaxLength(500)] public string? Address{get;set;} [MaxLength(1000)] public string? Note{get;set;} public DateTime CreatedAt{get;set;}=DateTime.UtcNow; public DateTime UpdatedAt{get;set;}=DateTime.UtcNow; [JsonIgnore] public List<Order> Orders{get;set;}=[]; }
public class Product { public int Id{get;set;} [MaxLength(30)] public string Code{get;set;}=""; [Required,MaxLength(160)] public string Name{get;set;}=""; [MaxLength(80)] public string? Color{get;set;} [MaxLength(40)] public string? Size{get;set;} [Range(0,999999999)] public decimal Price{get;set;} [Range(0,100000000)] public int Stock{get;set;} [MaxLength(1000)] public string? Note{get;set;} public DateTime CreatedAt{get;set;}=DateTime.UtcNow; public DateTime UpdatedAt{get;set;}=DateTime.UtcNow; }
public class Order { public int Id{get;set;} [MaxLength(40)] public string OrderCode{get;set;}=""; public int CustomerId{get;set;} public Customer? Customer{get;set;} public DateTime OrderDate{get;set;}=DateTime.UtcNow; public decimal TotalAmount{get;set;} [MaxLength(20)] public string Status{get;set;}="CONFIRMED"; [MaxLength(1000)] public string? Note{get;set;} public DateTime CreatedAt{get;set;}=DateTime.UtcNow; public DateTime UpdatedAt{get;set;}=DateTime.UtcNow; public List<OrderDetail> Details{get;set;}=[]; }
public class OrderDetail { public int Id{get;set;} public int OrderId{get;set;} [JsonIgnore] public Order? Order{get;set;} public int? ProductId{get;set;} public string ProductName{get;set;}=""; public string? Color{get;set;} public string? Size{get;set;} public int Quantity{get;set;} public decimal WeightKg{get;set;} public decimal Price{get;set;} public decimal Amount{get;set;} }
public class AppUser { public int Id{get;set;} [MaxLength(80)] public string UserName{get;set;}="admin"; public string PasswordHash{get;set;}=""; }


